using System.Collections;
using NUnit.Framework;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.TestTools;

namespace HR.Tests.PlayMode
{
    /// <summary>
    /// The scenes are generated by SceneBuilder, so these assert that the generator produced
    /// what the contract asks for — not that someone set it up correctly by hand once.
    /// </summary>
    public class SceneSmokeTests
    {
        // CONTRACT.md G-10: static orthographic camera, tunnel centre O at 46% of screen height.
        const float OrthoSize = 7.5f;
        const float CentreHeightFraction = 0.46f;

        [UnityTest]
        public IEnumerator Boot_scene_loads_with_a_camera()
        {
            yield return LoadScene("Boot");
            Assert.IsNotNull(Camera.main, "Boot has no MainCamera-tagged camera");
        }

        [UnityTest]
        public IEnumerator Main_scene_has_the_roots_every_generator_appends_to()
        {
            yield return LoadScene("Main");
            foreach (string root in new[] { "Tunnel", "UI", "Systems" })
                Assert.IsNotNull(GameObject.Find(root), $"Main is missing the '{root}' root");
        }

        [UnityTest]
        public IEnumerator Main_camera_frames_the_tunnel_centre_where_the_contract_puts_it()
        {
            yield return LoadScene("Main");

            var camera = Camera.main;
            Assert.IsNotNull(camera, "Main has no MainCamera-tagged camera");
            Assert.IsTrue(camera.orthographic, "camera must be orthographic");
            Assert.AreEqual(OrthoSize, camera.orthographicSize, 1e-4f);

            // World origin projected back to viewport space is the honest check: it survives a
            // future change to how the offset is computed, which asserting the y position would not.
            Vector3 viewport = camera.WorldToViewportPoint(Vector3.zero);
            Assert.AreEqual(0.5f, viewport.x, 1e-4f, "tunnel centre is off the horizontal middle");
            Assert.AreEqual(CentreHeightFraction, viewport.y, 1e-4f, "tunnel centre is at the wrong height");
        }

        [UnityTest]
        public IEnumerator Physics_runs_at_the_rate_the_contract_specifies()
        {
            yield return LoadScene("Main");

            // Guards the Unity 6 rational-timestep trap from the player's side: the editor can
            // report the right number while the built player runs at the default rate.
            Assert.AreEqual(1f / 90f, Time.fixedDeltaTime, 1e-6f);
            Assert.AreEqual(-14f, Physics2D.gravity.y, 1e-4f);
        }

        static IEnumerator LoadScene(string name)
        {
            var load = SceneManager.LoadSceneAsync(name, LoadSceneMode.Single);
            while (!load.isDone) yield return null;
            yield return null;
        }
    }
}
